#include <vector>
#include <cstddef>
#include <omp.h>

void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    // Ensure y has the correct size.
    y.resize(M);

    // Optional safety checks could be added, but omitted to match the requested signature.
    // Assumes:
    // - A.size() >= M * N
    // - x.size() >= N

    #pragma omp parallel for default(none) shared(A, x, y, M, N)
    for (std::size_t i = 0; i < M; ++i) {
        double sum = 0.0;
        const std::size_t row_start = i * N;
        for (std::size_t j = 0; j < N; ++j) {
            sum += A[row_start + j] * x[j];
        }
        y[i] = sum;
    }
}
